#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    vector<long long> A(n);
    for (int i = 0; i < n; i++) cin >> A[i];

    int m; cin >> m;
    vector<long long> B(m);
    for (int i = 0; i < m; i++) cin >> B[i];

    long long sumAall = 0, sumBall = 0;
    for (auto x : A) sumAall += x;
    for (auto x : B) sumBall += x;
    if ((n > m) && (sumAall == sumBall) && (A[0] == B[0])) {
        cout << -1 << "\n";
        return 0;
    }

    int i = 0, j = 0;
    long long sumA = 0, sumB = 0;
    int count = 0;

    while (i < n && j < m) {
        if (sumA == sumB) {
            sumA = A[i++];
            sumB = B[j++];
            count++;
        } else if (sumA < sumB) {
            if (i == n) break;
            sumA += A[i++];
        } else {
            if (j == m) break;
            sumB += B[j++];
        }
    }

    // After the loop, if sums are equal and all elements processed, print count
    if (sumA == sumB && i == n && j == m) {
        cout << count << "\n";
    } else {
        cout << -1 << "\n";
    }

    return 0;
}

